//! CPU-only tests for `/v1/evals`: real requests against a real store in a
//! private temporary directory, with runs generated by the real batch worker
//! driven by scripted engine signals instead of a model. Every object the
//! API answers with is checked against the pinned `OpenAI` schemas.

use std::path::PathBuf;
use std::sync::mpsc;
use std::sync::{Arc, Condvar, Mutex};
use std::time::{Duration, Instant};

use axum::body::Body;
use axum::http::{Method, Request, StatusCode};
use serde_json::{Map, Value, json};

use local_engine::bonsai_model::{PromptCacheSource, StopReason};
use local_engine::{ChatRequest, Event, GenerationStats, Signal, Stats};
use local_services::Store;

use super::super::QueueDepth;
use super::super::batches::{Batches, Config, Generation, Submit};
use super::{Evals, matches};

const MODEL: &str = "local";
/// The `OpenAI` schemas of the Evals API objects, extracted (with every
/// schema they reference) from the pinned `OpenAI` `OpenAPI` document.
const SCHEMAS: &str = include_str!("eval_openapi_schemas.json");

struct Scratch {
    _dir: tempfile::TempDir,
    root: PathBuf,
}

impl Scratch {
    fn new() -> Self {
        let dir = tempfile::tempdir().expect("temporary directory");
        // SQLite refuses a path through a symlink (macOS `/var`).
        let root = dir
            .path()
            .canonicalize()
            .expect("canonical temporary directory")
            .join("services");
        Self { _dir: dir, root }
    }

    fn store(&self) -> Store {
        Store::open(&self.root).expect("store opens")
    }
}

fn stats() -> Stats {
    Stats {
        stop_reason: StopReason::Eos,
        cache_source: PromptCacheSource::None,
        reasoning_tokens: 0,
        generation: GenerationStats {
            prompt_tokens: 7,
            generated_tokens: 2,
            ..GenerationStats::default()
        },
    }
}

fn prompt(request: &ChatRequest) -> String {
    request
        .messages
        .last()
        .map(|message| message.content.clone())
        .unwrap_or_default()
}

fn answer(text: String) -> Generation {
    let mut signals = vec![
        Signal::Event(Event::Content(text)),
        Signal::Event(Event::Finished(Box::new(stats()))),
    ]
    .into_iter();
    Generation {
        next: Box::new(move |_: Option<Duration>| Ok(signals.next())),
        cancel: Arc::new(|| {}),
    }
}

/// A generation that produces nothing until it is cancelled, then ends.
fn blocked() -> Generation {
    let gate = Arc::new((Mutex::new(false), Condvar::new()));
    let opener = Arc::clone(&gate);
    Generation {
        next: Box::new(move |_: Option<Duration>| {
            let (lock, signal) = &*gate;
            drop(
                signal
                    .wait_while(lock.lock().expect("gate"), |cancelled| !*cancelled)
                    .expect("gate"),
            );
            Ok(None)
        }),
        cancel: Arc::new(move || {
            let (lock, signal) = &*opener;
            *lock.lock().expect("gate") = true;
            signal.notify_all();
        }),
    }
}

/// A fake model: sampling `1+1=` answers `2`, `2+2=` answers `5`, anything
/// else `6`, and `block=` (when `blocking`) runs until cancelled; a grader
/// prompt `Rate X for Q` scores 1 for the answer `5` and 8 otherwise.
fn fake(blocking: bool) -> (Submit, mpsc::Receiver<()>) {
    let (started, receiver) = mpsc::channel();
    let started = Mutex::new(started);
    let submit: Submit = Arc::new(move |request: ChatRequest| -> crate::Result<Generation> {
        let text = prompt(&request);
        if let Some(rest) = text.strip_prefix("Rate ") {
            let score = if rest.starts_with("5 ") { 1 } else { 8 };
            return Ok(answer(format!("{{\"result\": {score}}}")));
        }
        Ok(match text.as_str() {
            "block=" if blocking => {
                let _ = started.lock().expect("started").send(());
                blocked()
            }
            "1+1=" => answer("2".into()),
            "2+2=" => answer("5".into()),
            _ => answer("6".into()),
        })
    });
    (submit, receiver)
}

struct Server {
    batches: Arc<Batches>,
    evals: Arc<Evals>,
}

impl Server {
    fn start(store: &Store, submit: Submit) -> Self {
        let batches = Batches::spawn(
            store.clone(),
            submit,
            Config {
                model: MODEL.into(),
                thinking: false,
                cipher: None,
                depth: QueueDepth::default(),
            },
        )
        .expect("batch worker starts");
        let evals = Evals::spawn(store.clone(), &batches, MODEL.into()).expect("eval worker");
        Self { batches, evals }
    }

    async fn stop(&self) {
        self.evals.close();
        self.batches.close();
        self.evals.drained().await;
        self.batches.drained().await;
    }

    async fn send(&self, method: Method, uri: &str, body: &Value) -> (StatusCode, Value) {
        let body = if body.is_null() {
            Body::empty()
        } else {
            Body::from(body.to_string())
        };
        let request = Request::builder()
            .method(method)
            .uri(uri)
            .header("host", "127.0.0.1:8106")
            .body(body)
            .expect("request");
        let (parts, body) = request.into_parts();
        match self.evals.dispatch(&parts, body).await {
            Ok(answer) => answer,
            Err((status, message)) => (status, json!({"error": {"message": message}})),
        }
    }
}

/// Turn each `oneOf` offering `EvalItem` into an `anyOf`: the pinned document
/// lists `EvalItem` beside `EasyInputMessage` (or a plain chat message) for
/// template messages, and every `{"role", "content"}` message matches both,
/// so `oneOf` would refuse the documented examples themselves.
fn relax_message_choices(value: &mut Value) {
    match value {
        Value::Object(map) => {
            let ambiguous = map
                .get("oneOf")
                .and_then(Value::as_array)
                .is_some_and(|choices| {
                    choices
                        .iter()
                        .any(|choice| choice["$ref"] == "#/components/schemas/EvalItem")
                });
            if ambiguous && let Some(choices) = map.remove("oneOf") {
                map.insert("anyOf".into(), choices);
            }
            map.values_mut().for_each(relax_message_choices);
        }
        Value::Array(items) => items.iter_mut().for_each(relax_message_choices),
        _ => {}
    }
}

/// Check `value` against the pinned schema `name`.
fn conforms(name: &str, value: &Value) {
    let mut spec: Value = serde_json::from_str(SCHEMAS).expect("schema fixture");
    relax_message_choices(&mut spec);
    let mut root = Map::new();
    root.insert("$ref".into(), json!(format!("#/components/schemas/{name}")));
    root.insert("components".into(), spec["components"].clone());
    let validator = jsonschema::options()
        .build(&Value::Object(root))
        .expect("the pinned schema compiles");
    let errors: Vec<String> = validator
        .iter_errors(value)
        .map(|error| error.to_string())
        .collect();
    assert!(errors.is_empty(), "{name}: {errors:#?}\n{value:#}");
}

fn eval_body() -> Value {
    json!({
        "name": "arithmetic",
        "metadata": {"suite": "smoke"},
        "data_source_config": {
            "type": "custom",
            "item_schema": {"type": "object", "properties": {"q": {"type": "string"},
                            "a": {"type": "string"}}, "required": ["q", "a"]},
            "include_sample_schema": true,
        },
        "testing_criteria": [
            {"type": "string_check", "name": "exact", "input": "{{sample.output_text}}",
             "reference": "{{item.a}}", "operation": "eq"},
            {"type": "score_model", "name": "judge", "model": MODEL, "range": [0, 10],
             "pass_threshold": 5,
             "input": [{"role": "user", "content": "Rate {{sample.output_text}} for {{item.q}}"}]},
        ],
    })
}

fn run_body(questions: &[(&str, &str)]) -> Value {
    let content: Vec<Value> = questions
        .iter()
        .map(|(q, a)| json!({"item": {"q": q, "a": a}}))
        .collect();
    json!({
        "name": "bonsai",
        "data_source": {
            "type": "completions",
            "model": MODEL,
            "input_messages": {"type": "template",
                               "template": [{"role": "user", "content": "{{item.q}}="}]},
            "sampling_params": {"temperature": 0.0, "max_completion_tokens": 16},
            "source": {"type": "file_content", "content": content},
        },
    })
}

const QUESTIONS: [(&str, &str); 3] = [("1+1", "2"), ("2+2", "4"), ("3+3", "6")];

/// The run once it is terminal (or after ten seconds, for the assertion to
/// fail on). The Evals API, like `OpenAI`'s, announces a run's end only
/// through its status, so a client can only poll it: a short, bounded
/// cadence here.
async fn settled(server: &Server, eval: &str, run: &str) -> Value {
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        let (status, value) = server
            .send(
                Method::GET,
                &format!("/v1/evals/{eval}/runs/{run}"),
                &Value::Null,
            )
            .await;
        assert_eq!(status, StatusCode::OK, "{value}");
        let terminal = matches!(
            value["status"].as_str(),
            Some("completed" | "canceled" | "failed")
        );
        if terminal || Instant::now() > deadline {
            return value;
        }
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
}

async fn create_eval(server: &Server) -> String {
    let (status, eval) = server.send(Method::POST, "/v1/evals", &eval_body()).await;
    assert_eq!(status, StatusCode::CREATED, "{eval}");
    conforms("Eval", &eval);
    eval["id"].as_str().expect("eval id").to_owned()
}

async fn create_run(server: &Server, eval: &str, questions: &[(&str, &str)]) -> Value {
    let (status, run) = server
        .send(
            Method::POST,
            &format!("/v1/evals/{eval}/runs"),
            &run_body(questions),
        )
        .await;
    assert_eq!(status, StatusCode::CREATED, "{run}");
    conforms("EvalRun", &run);
    run
}

#[test]
fn only_eval_paths_match() {
    assert!(matches("/v1/evals"));
    assert!(matches("/v1/evals/eval_1/runs"));
    assert!(!matches("/v1/evalsx"));
    assert!(!matches("/v1/batches"));
}

#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::too_many_lines)]
async fn a_run_samples_grades_and_reports_in_the_pinned_shapes() {
    let scratch = Scratch::new();
    let store = scratch.store();
    let (submit, _) = fake(false);
    let server = Server::start(&store, submit);
    let eval = create_eval(&server).await;
    let run = create_run(&server, &eval, &QUESTIONS).await;
    let id = run["id"].as_str().expect("run id");
    assert_eq!(
        run["report_url"],
        format!("http://127.0.0.1:8106/v1/evals/{eval}/runs/{id}")
    );
    let done = settled(&server, &eval, id).await;
    conforms("EvalRun", &done);
    assert_eq!(done["status"], "completed", "{done}");
    assert_eq!(done["model"], MODEL);
    assert_eq!(
        done["result_counts"],
        json!({"total": 3, "errored": 0, "failed": 1, "passed": 2})
    );
    assert_eq!(
        done["per_testing_criteria_results"],
        json!([{"testing_criteria": "exact", "passed": 2, "failed": 1},
               {"testing_criteria": "judge", "passed": 2, "failed": 1}])
    );
    assert_eq!(done["per_model_usage"][0]["model_name"], MODEL);
    assert_eq!(done["per_model_usage"][0]["invocation_count"], 6);

    let (status, items) = server
        .send(
            Method::GET,
            &format!("/v1/evals/{eval}/runs/{id}/output_items?limit=2"),
            &Value::Null,
        )
        .await;
    assert_eq!(status, StatusCode::OK, "{items}");
    conforms("EvalRunOutputItemList", &items);
    assert_eq!(items["has_more"], true);
    let first = &items["data"][0];
    conforms("EvalRunOutputItem", first);
    assert_eq!(first["status"], "pass");
    assert_eq!(first["sample"]["output"][0]["content"], "2");
    assert_eq!(first["sample"]["max_completion_tokens"], 16);
    assert_eq!(first["results"][1]["score"], 8.0);
    let wrong = &items["data"][1];
    assert_eq!(wrong["status"], "fail");
    assert_eq!(wrong["results"][0]["passed"], false);
    let (status, failing) = server
        .send(
            Method::GET,
            &format!("/v1/evals/{eval}/runs/{id}/output_items?status=fail"),
            &Value::Null,
        )
        .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(failing["data"].as_array().map(Vec::len), Some(1));
    let item = wrong["id"].as_str().expect("item id");
    let (status, one) = server
        .send(
            Method::GET,
            &format!("/v1/evals/{eval}/runs/{id}/output_items/{item}"),
            &Value::Null,
        )
        .await;
    assert_eq!((status, &one), (StatusCode::OK, wrong));

    // The generation went through ordinary, visible batches.
    let batches = store
        .list_batches(&local_services::batches::ListBatches::default())
        .expect("batches");
    assert_eq!(batches.data.len(), 2);
    assert!(
        batches
            .data
            .iter()
            .all(|batch| batch.metadata["eval_run_id"] == id)
    );

    let (status, runs) = server
        .send(Method::GET, &format!("/v1/evals/{eval}/runs"), &Value::Null)
        .await;
    assert_eq!(status, StatusCode::OK);
    conforms("EvalRunList", &runs);
    let (status, evals) = server
        .send(Method::GET, "/v1/evals?order=desc", &Value::Null)
        .await;
    assert_eq!(status, StatusCode::OK);
    conforms("EvalList", &evals);

    let (status, deleted) = server
        .send(
            Method::DELETE,
            &format!("/v1/evals/{eval}/runs/{id}"),
            &Value::Null,
        )
        .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(
        deleted,
        json!({"object": "eval.run.deleted", "deleted": true, "run_id": id})
    );
    let (status, deleted) = server
        .send(Method::DELETE, &format!("/v1/evals/{eval}"), &Value::Null)
        .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(
        deleted,
        json!({"object": "eval.deleted", "deleted": true, "eval_id": eval})
    );
    server.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::too_many_lines)]
async fn requests_are_validated_and_errors_have_the_documented_statuses() {
    let scratch = Scratch::new();
    let store = scratch.store();
    let (submit, _) = fake(false);
    let server = Server::start(&store, submit);
    let eval = create_eval(&server).await;
    let cases = [
        (
            Method::POST,
            "/v1/evals".to_owned(),
            json!({"data_source_config": {"type": "logs"}, "testing_criteria": []}),
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::POST,
            "/v1/evals".to_owned(),
            json!({"unknown": 1}),
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::GET,
            "/v1/evals?limit=0".to_owned(),
            Value::Null,
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::GET,
            "/v1/evals?order=sideways".to_owned(),
            Value::Null,
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::GET,
            "/v1/evals?limit=1&limit=2".to_owned(),
            Value::Null,
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::GET,
            "/v1/evals?after=eval_missing".to_owned(),
            Value::Null,
            StatusCode::NOT_FOUND,
        ),
        (
            Method::GET,
            "/v1/evals/eval_missing".to_owned(),
            Value::Null,
            StatusCode::NOT_FOUND,
        ),
        (
            Method::GET,
            format!("/v1/evals/{eval}/runs?status=done"),
            Value::Null,
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::GET,
            format!("/v1/evals/{eval}/runs/evalrun_missing"),
            Value::Null,
            StatusCode::NOT_FOUND,
        ),
        (
            Method::POST,
            format!("/v1/evals/{eval}/runs"),
            json!({"data_source": {"type": "jsonl", "source": {"type": "file_content", "content": [{"item": {"q": 1}}]}}}),
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::POST,
            format!("/v1/evals/{eval}/runs"),
            json!({"data_source": {"type": "completions", "model": "gpt-4o", "source": {"type": "file_content", "content": []}}}),
            StatusCode::BAD_REQUEST,
        ),
        (
            Method::PUT,
            "/v1/evals".to_owned(),
            Value::Null,
            StatusCode::NOT_FOUND,
        ),
        (
            Method::GET,
            format!("/v1/evals/{eval}/runs/evalrun_x/other"),
            Value::Null,
            StatusCode::NOT_FOUND,
        ),
    ];
    for (method, uri, body, expected) in cases {
        let (status, answer) = server.send(method.clone(), &uri, &body).await;
        assert_eq!(status, expected, "{method} {uri}: {answer}");
    }
    let (status, updated) = server
        .send(
            Method::POST,
            &format!("/v1/evals/{eval}"),
            &json!({"name": "renamed", "metadata": {"k": "v"}}),
        )
        .await;
    assert_eq!(status, StatusCode::OK);
    conforms("Eval", &updated);
    assert_eq!(
        (updated["name"].as_str(), &updated["metadata"]),
        (Some("renamed"), &json!({"k": "v"}))
    );
    server.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn cancelling_a_run_interrupts_its_running_line() {
    let scratch = Scratch::new();
    let store = scratch.store();
    let (submit, started) = fake(true);
    let server = Server::start(&store, submit);
    let eval = create_eval(&server).await;
    let run = create_run(
        &server,
        &eval,
        &[("1+1", "2"), ("block", "x"), ("3+3", "6")],
    )
    .await;
    let id = run["id"].as_str().expect("run id");
    tokio::task::spawn_blocking(move || started.recv_timeout(Duration::from_secs(10)))
        .await
        .expect("joined")
        .expect("the blocking line started");
    let (status, eval_deleted) = server
        .send(Method::DELETE, &format!("/v1/evals/{eval}"), &Value::Null)
        .await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{eval_deleted}");
    let (status, canceled) = server
        .send(
            Method::POST,
            &format!("/v1/evals/{eval}/runs/{id}/cancel"),
            &Value::Null,
        )
        .await;
    assert_eq!(status, StatusCode::OK, "{canceled}");
    conforms("EvalRun", &canceled);
    assert_eq!(canceled["status"], "canceled");
    // The batch the run created ends cancelled, without running its last line.
    let deadline = Instant::now() + Duration::from_secs(10);
    let batch = loop {
        let batch = store
            .list_batches(&local_services::batches::ListBatches::default())
            .expect("batches")
            .data
            .remove(0);
        if batch.status.is_terminal() || Instant::now() > deadline {
            break batch;
        }
        tokio::time::sleep(Duration::from_millis(5)).await;
    };
    assert_eq!(
        batch.status,
        local_services::batches::BatchStatus::Cancelled
    );
    assert_eq!(batch.request_counts.completed, 1);
    let (status, again) = server
        .send(
            Method::POST,
            &format!("/v1/evals/{eval}/runs/{id}/cancel"),
            &Value::Null,
        )
        .await;
    assert_eq!(
        (status, &again["status"]),
        (StatusCode::OK, &json!("canceled"))
    );
    let (_, items) = server
        .send(
            Method::GET,
            &format!("/v1/evals/{eval}/runs/{id}/output_items"),
            &Value::Null,
        )
        .await;
    assert_eq!(items["data"], json!([]));
    server.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_restarted_server_resumes_an_interrupted_run() {
    let scratch = Scratch::new();
    let store = scratch.store();
    let (submit, started) = fake(true);
    let server = Server::start(&store, submit);
    let eval = create_eval(&server).await;
    let run = create_run(
        &server,
        &eval,
        &[("1+1", "2"), ("block", "6"), ("3+3", "6")],
    )
    .await;
    let id = run["id"].as_str().expect("run id").to_owned();
    tokio::task::spawn_blocking(move || started.recv_timeout(Duration::from_secs(10)))
        .await
        .expect("joined")
        .expect("the blocking line started");
    // Shutdown interrupts the running line, which stays pending.
    server.stop().await;
    let (_, stopped) = server
        .send(
            Method::GET,
            &format!("/v1/evals/{eval}/runs/{id}"),
            &Value::Null,
        )
        .await;
    assert_eq!(stopped["status"], "in_progress");

    // The next server (whose model no longer blocks) picks it up.
    let (submit, _) = fake(false);
    let restarted = Server::start(&scratch.store(), submit);
    let done = settled(&restarted, &eval, &id).await;
    assert_eq!(done["status"], "completed", "{done}");
    assert_eq!(
        done["result_counts"],
        json!({"total": 3, "errored": 0, "failed": 0, "passed": 3})
    );
    // One sampling and one grading batch, the sampling one resumed.
    assert_eq!(
        store
            .list_batches(&local_services::batches::ListBatches::default())
            .expect("batches")
            .data
            .len(),
        2
    );
    restarted.stop().await;
}

/// Chat Completions takes no `seed` (the specification deprecates it), so a
/// sample generated through it reports the seed every Chat request samples
/// with: the engine's default.
#[test]
fn chat_sampled_evals_report_the_seed_chat_completions_samples_with() {
    assert_eq!(
        u64::try_from(local_services::evals::CHAT_COMPLETIONS_SEED).expect("non-negative"),
        crate::GenerateParams::default().seed
    );
}
